import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"API-Zugangsdaten","description":"Zugangsdaten für die Programmierschnittstelle erzeugen und sicher verwalten.","frontmatter":{"title":"API-Zugangsdaten","description":"Zugangsdaten für die Programmierschnittstelle erzeugen und sicher verwalten."},"headers":[],"relativePath":"integrationen/api-zugangsdaten.md","filePath":"integrationen/api-zugangsdaten.md","lastUpdated":1786090882000}'),a={name:"integrationen/api-zugangsdaten.md"};function s(l,e,d,o,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="api-zugangsdaten" tabindex="-1">API-Zugangsdaten <a class="header-anchor" href="#api-zugangsdaten" aria-label="Permalink to &quot;API-Zugangsdaten&quot;">​</a></h1><p>Für den Zugriff über die Programmierschnittstelle brauchen eigene Anwendungen <strong>API Zugangsdaten</strong>.</p><p>Sie finden sie unter <strong>Profil &amp; Einstellungen → API Zugangsdaten</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Persönlich und weitreichend</p><blockquote><p><em>Dies sind Ihre persönlichen API Anmeldedaten. Sie werden benötigt, um die API zu nutzen. Ihre persönlichen API Anmeldeinformationen gewähren Zugriff auf <strong>alle Daten in Ihren Spaces</strong>. Geben Sie diese Anmeldeinformationen nur an Dienste und Anwendungen von Drittanbietern weiter, denen Sie vertrauen.</em></p></blockquote><p>Zwei Dinge daran sind wichtig:</p><ol><li><strong>Persönlich, nicht space-gebunden.</strong> Die Zugangsdaten reichen so weit wie Ihr eigener Zugriff — über <strong>alle</strong> Spaces hinweg, auch über solche, die mit dem Vorhaben nichts zu tun haben.</li><li><strong>Sie hängen an Ihrem Konto.</strong> Verlässt jemand das Unternehmen und wird sein Konto gelöscht, hören alle damit gebauten Anbindungen auf zu funktionieren.</li></ol></div><h2 id="zugangsdaten-erstellen" tabindex="-1">Zugangsdaten erstellen <a class="header-anchor" href="#zugangsdaten-erstellen" aria-label="Permalink to &quot;Zugangsdaten erstellen&quot;">​</a></h2><ol><li>Klicken Sie auf <strong>Zugangsdaten erstellen</strong>.</li><li>Vergeben Sie unter <em>Wählen Sie einen Namen für Ihre Zugangsdaten</em> eine Bezeichnung.</li><li>Wählen Sie unter <em>Diese Zugangsdaten gewähren:</em> die Berechtigung.</li><li>Bestätigen Sie mit <strong>Erstellen</strong>.</li></ol><h3 id="berechtigung" tabindex="-1">Berechtigung <a class="header-anchor" href="#berechtigung" aria-label="Permalink to &quot;Berechtigung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Auswahl</th><th>Umfang</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td><em>Vollen Zugriff auf Ihre Spaces</em></td></tr><tr><td><strong>Nur lesen</strong></td><td><em>Nur Lesezugriff auf Ihre Spaces</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Im Zweifel „Nur lesen&quot;</p><p>Für Auswertungen, Berichte und Datenexporte genügt Lesezugriff. Wählen Sie <em>Admin</em> nur, wenn die Anwendung tatsächlich schreiben muss.</p><p>Ein Auslesefehler in einem Skript mit Lesezugriff kostet nichts. Derselbe Fehler mit Vollzugriff kann Daten überschreiben.</p></div><div class="tip custom-block"><p class="custom-block-title">Je Anwendung eigene Zugangsdaten</p><p>Legen Sie nicht einen Schlüssel für alles an, sondern einen je Anwendung — mit sprechendem Namen. Dann können Sie einzelne widerrufen, ohne alles andere lahmzulegen.</p></div><h2 id="nur-einmal-sichtbar" tabindex="-1">Nur einmal sichtbar <a class="header-anchor" href="#nur-einmal-sichtbar" aria-label="Permalink to &quot;Nur einmal sichtbar&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Sofort sicher notieren</p><p>Nach dem Erstellen erscheint:</p><blockquote><p><strong>Ihre Zugangsdaten sind verfügbar</strong></p><p><strong>Speichern Sie jetzt Ihren Autorisierungsschlüssel und Ihr Passwort.</strong></p><p><em>Dies ist der einzige Zeitpunkt, zu dem die Zugangsdaten angezeigt oder heruntergeladen werden können. Später können sie nicht mehr wiederhergestellt werden. Sie können Ihre API Zugangsdaten jedoch jederzeit löschen und neue erzeugen.</em></p></blockquote><p>Die Zugangsdaten bestehen aus <strong>Autorisierungsschlüssel</strong> und <strong>Passwort</strong>.</p><p>Legen Sie beides in einem Passwortmanager ab — <strong>nicht</strong> in einer Textdatei, einem Chat oder einer E-Mail.</p></div><p>Geht etwas verloren, löschen Sie die Zugangsdaten und erzeugen neue. Die Anbindung muss dann angepasst werden.</p><h2 id="sicherheit" tabindex="-1">Sicherheit <a class="header-anchor" href="#sicherheit" aria-label="Permalink to &quot;Sicherheit&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Wo Zugangsdaten nicht hingehören</p><ul><li><strong>Nicht in öffentliche Repositories.</strong> Automatische Scanner finden solche Schlüssel binnen Minuten.</li><li><strong>Nicht in Frontend-Code.</strong> Alles, was im Browser läuft, ist einsehbar.</li><li><strong>Nicht in Chats, Tickets oder Folien.</strong></li><li><strong>Nicht in Screenshots.</strong></li></ul></div><div class="tip custom-block"><p class="custom-block-title">Regelmäßig aufräumen</p><p>Gehen Sie die Liste Ihrer Zugangsdaten durch und löschen Sie, was nicht mehr gebraucht wird. Ein vergessener Schlüssel bleibt gültig, bis ihn jemand entfernt.</p></div><h2 id="woran-sie-api-zugriffe-erkennen" tabindex="-1">Woran Sie API-Zugriffe erkennen <a class="header-anchor" href="#woran-sie-api-zugriffe-erkennen" aria-label="Permalink to &quot;Woran Sie API-Zugriffe erkennen&quot;">​</a></h2><p>Einträge, die über die Schnittstelle entstanden sind, zeigen in der Spalte <strong>Erstellt von</strong> den Wert <strong>API Zugangsdaten</strong> statt eines Personennamens.</p><p>Im <a href="/docs/grids/versionsverlauf">Versionsverlauf</a> erscheinen entsprechende Änderungen als <strong>System oder Flow</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Nützlich bei der Fehlersuche</p><p>Ändert sich ein Wert unerwartet, klärt der Versionsverlauf schnell, ob ein Mensch, ein Flow oder eine angebundene Anwendung dahintersteckt.</p></div><h2 id="technische-eckdaten" tabindex="-1">Technische Eckdaten <a class="header-anchor" href="#technische-eckdaten" aria-label="Permalink to &quot;Technische Eckdaten&quot;">​</a></h2><p>Für die Entwicklung einer Anbindung:</p><table tabindex="0"><thead><tr><th>Merkmal</th><th>Wert</th></tr></thead><tbody><tr><td>Schnittstellenversion</td><td>2</td></tr><tr><td>Aufbau</td><td>Ressourcen verweisen über Verknüpfungen aufeinander</td></tr><tr><td>Anmeldung</td><td>Autorisierungsschlüssel und Passwort</td></tr><tr><td>Space-Kennung</td><td>in den <a href="/docs/spaces/einstellungen">Space-Einstellungen</a> unter <em>Space Identifikator</em></td></tr><tr><td>Feldbezeichner</td><td>über <strong>Feldkey verwalten</strong> am jeweiligen Feld</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Diese Dokumentation ist keine Schnittstellenreferenz</p><p>Eine vollständige Beschreibung der verfügbaren Aufrufe ist nicht Teil dieser Nutzerdokumentation. Wenden Sie sich für Entwicklerunterlagen an den Support über den Chat.</p></div><h2 id="braucht-es-wirklich-die-schnittstelle" tabindex="-1">Braucht es wirklich die Schnittstelle? <a class="header-anchor" href="#braucht-es-wirklich-die-schnittstelle" aria-label="Permalink to &quot;Braucht es wirklich die Schnittstelle?&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Oft geht es einfacher</p><table tabindex="0"><thead><tr><th>Ziel</th><th>Einfacherer Weg</th></tr></thead><tbody><tr><td>Daten aus einem System übernehmen</td><td><a href="/docs/grids/csv-import">CSV-Import</a></td></tr><tr><td>Daten an ein System übergeben</td><td><a href="/docs/grids/csv-export">CSV-Export</a> oder <a href="/docs/integrationen/webhooks">Webhook</a></td></tr><tr><td>Ein anderes System aufrufen</td><td>Flow-Schritt <strong>HTTP-Anfrage</strong></td></tr><tr><td>Flow von außen starten</td><td><a href="/docs/flows/webhook-trigger">Webhook-Auslöser</a></td></tr><tr><td>Daten anzeigen</td><td><a href="/docs/seiten/portal-veroeffentlichen">Portal</a></td></tr></tbody></table><p>Die Schnittstelle lohnt sich, wenn eine eigene Anwendung dauerhaft und in beide Richtungen mit ApptiveGrid arbeitet.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/integrationen/ueberblick">Überblick</a></li><li><a href="/docs/integrationen/webhooks">Webhooks</a></li><li><a href="/docs/erste-schritte/konto-und-anmeldung">Konto und Anmeldung</a></li></ul>',28)])])}const m=n(a,[["render",s]]);export{u as __pageData,m as default};
